      code: currentRuntimeConfig.code || "MANAGED_SUBSCRIPTION_ENVIRONMENT_CHANGED",
    });
  }
  if (!isHttpOk(msg.statusCode)) {
    return rejectRuntime(409, "Опубликованные правила подписки сейчас недоступны", {
