    && Number.isInteger(policy.lifecycle?.activationWindowDays)
    && policy.lifecycle.activationWindowDays === 0
    && toStr(policy.lifecycle?.fixedActivationAt) === REGIONAL_ACTIVATION_FALLBACK_AT
