  const decision = msg._managedSubscriptionPolicyDecision;
  if (!isObj(decision) || decision.eligible !== true
    || decision.policyVersion !== ctx.managedRuntime?.policy?.policyVersion) {
    if (isRecheck) {
      return prepareFailedUpdate(
        ctx,
        409,
        "Правила подписки не разрешили эту запись",
        "MANAGED_SUBSCRIPTION_POLICY_BLOCKED",
      );
    }
    return finishError(ctx, 409, "Правила подписки не разрешили эту запись", {
      code: "MANAGED_SUBSCRIPTION_POLICY_BLOCKED",
    });
  }
  if (decision.benefit?.kind !== "FREE_ENTITLEMENT") {
    if (isRecheck) {
      return prepareFailedUpdate(
        ctx,
        409,
        "Правила подписки не покрывают это действие",
        "MANAGED_SUBSCRIPTION_BENEFIT_NOT_APPLICABLE",
      );
    }
    return finishError(ctx, 409, "Правила подписки не покрывают это действие", {
      code: "MANAGED_SUBSCRIPTION_BENEFIT_NOT_APPLICABLE",
    });
  }
  ctx.managedDecision = {
    policyVersion: decision.policyVersion,
    policyDigest: ctx.managedRuntime.policyDigest,
    subscriptionInstanceId: ctx.managedRuntime.subscriptionInstanceId,
    usageUnits: decision.usageUnits,
    benefit: decision.benefit || null,
    evaluatedAt: decision.evaluatedAt,
  };
  delete msg._managedSubscriptionPolicyInput;
  delete msg._managedSubscriptionPolicyDecision;
  if (isRecheck) return prepareBookingCreate(ctx);
  return prepareOperationFind(ctx);
}

if (ctx.step === "managed_entitlement_reserve") {
  const result = unwrapRecord(msg.payload);
  if (!isHttpOk(msg.statusCode) || !result || result.schemaVersion !== 1
    || result.subscriptionInstanceId !== (
      ctx.managedRuntime?.subscriptionInstanceId || ctx.managedSubscriptionInstanceId
    )
    || !Number.isInteger(result.aggregateRevision) || result.aggregateRevision < 1) {
    return prepareFailedUpdate(
      ctx,
      Number(msg.statusCode) >= 400 && Number(msg.statusCode) < 500 ? Number(msg.statusCode) : 502,
      "ЦУП не подтвердил резерв льготы подписки",
      toStr(result?.code || result?.error?.code) || "SUBSCRIPTION_ENTITLEMENT_RESERVE_FAILED",
    );
  }
  if (result.outcome === "FULL_PRICE_WITHOUT_SUBSCRIPTION") {
    const blockers = asArray(result.blockers);
    if (result.operationId !== null || result.operationState !== null || result.decision !== null
      || blockers.length !== 1 || blockers[0]?.code !== "ACTIVE_SERVICES_LIMIT_REACHED") {
      return prepareFailedUpdate(
        ctx,
        502,
        "ЦУП вернул небезопасный переход на полную стоимость",
        "SUBSCRIPTION_FULL_PRICE_FALLBACK_INVALID",
      );
    }
    return prepareFullPriceFallbackUpdate(ctx, blockers);
  }
  if (result.outcome !== "RESERVED" || !toStr(result.operationId)
    || !["RESERVED", "CONFIRMED"].includes(result.operationState)
    || typeof result.replayed !== "boolean"
    || (result.operationState === "CONFIRMED" && result.replayed !== true)
    || asArray(result.blockers).length > 0
    || !validEntitlementDecision(ctx, result.decision)) {
    return prepareFailedUpdate(
      ctx,
      502,
      "ЦУП вернул несогласованный резерв льготы",
      "SUBSCRIPTION_ENTITLEMENT_RESERVE_INVALID",
    );
  }
  ctx.managedEntitlementOperationId = toStr(result.operationId);
  ctx.managedDecision = result.decision;
  ctx.managedEntitlementReplayedConfirmed = result.operationState === "CONFIRMED";
  return prepareManagedEntitlementBind(ctx);
}

if (ctx.step === "operation_entitlement_bind") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Льгота зарезервирована в ЦУП; локальная связь требует сверки", {
      code: "SUBSCRIPTION_ENTITLEMENT_BIND_PENDING",
    });
  }
  if (ctx.managedDecision?.money?.finalPriceMinor > 0) {
    ctx.entitlementReleaseNext = "pricing_not_configured";
    return prepareManagedEntitlementRelease(ctx, "PROVIDER_REJECTED");
  }
  if (ctx.managedEntitlementReplayedConfirmed === true) {
    return finishPending(ctx, "Льгота уже подтверждена в ЦУП; запись Viva требует точной сверки", {
      code: "SUBSCRIPTION_ENTITLEMENT_CONFIRMED_RECONCILIATION_REQUIRED",
    });
  }
  if (ctx.caller === "split_create_preflight") {
    return preparePrecreatedAttempt(ctx);
  }
  return prepareBookingCreate(ctx);
}

if (ctx.step === "operation_full_price_fallback") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Переход на полную стоимость ожидает локального подтверждения", {
      code: "SUBSCRIPTION_FULL_PRICE_FALLBACK_PENDING",
    });
  }
  return finishFullPriceFallback(ctx, ctx.fullPriceFallbackBlockers);
}

if (ctx.step === "operation_find") {
  if (msg.error || !Array.isArray(msg.payload) || msg.payload.some((row) => !isObj(row))
    || (ctx.action !== "release" && msg.payload.length > 1)) {
    return finishPending(ctx, "Формат ответа Mongo требует сверки", {
      code: "SUBSCRIPTION_BOOKING_OPERATION_READ_INVALID",
    });
  }
  const rows = asArray(msg.payload);
  if (ctx.action === "release") {
    if (rows.length === 0) {
      return finishReleased(ctx, { operationFound: false });
    }
    if (rows.length > 1) {
      return finishError(ctx, 502, "Найдено несколько операций для отменённой записи", {
        code: "SUBSCRIPTION_BOOKING_RELEASE_OPERATION_AMBIGUOUS",
      });
    }
    const releaseOperation = isObj(rows[0]) ? rows[0] : null;
    if (!releaseOperation) {
      return finishError(ctx, 502, "Операция дневного посещения имеет неизвестный формат", {
        code: "SUBSCRIPTION_BOOKING_RELEASE_OPERATION_INVALID",
      });
    }
    if (normalizeId(releaseOperation.clientSubscriptionId) !== normalizeId(ctx.clientSubscriptionId)) {
      return finishError(ctx, 409, "Абонемент отменённой записи не совпал с дневной операцией", {
        code: "SUBSCRIPTION_BOOKING_RELEASE_SUBSCRIPTION_MISMATCH",
      });
    }
    ctx.managedEnvironment = toStr(releaseOperation.managedEnvironment) || "PROD";
    if (asArray(releaseOperation.releasedBookingIds).some((id) => normalizeId(id) === normalizeId(ctx.releaseBookingId))) {
      return finishReleased(ctx, { operationFound: true, alreadyReleased: true });
    }
    const operationBookingId = normalizeId(releaseOperation.bookingId || releaseOperation.upstreamBookingId);
    if (operationBookingId && operationBookingId !== normalizeId(ctx.releaseBookingId)) {
      return finishError(ctx, 409, "Отменённая запись не совпала с подтверждённой операцией", {
        code: "SUBSCRIPTION_BOOKING_RELEASE_OPERATION_MISMATCH",
      });
    }
    if (["FAILED", "RELEASED"].includes(String(releaseOperation.state || ""))) {
      return finishReleased(ctx, { operationFound: true, alreadyReleased: true });
    }
    if (!["PREPARED", "PENDING_CONFIRMATION", "CONFIRMED"].includes(String(releaseOperation.state || ""))) {
      return finishError(ctx, 409, "Операция дневного посещения требует ручной сверки", {
        code: "SUBSCRIPTION_BOOKING_RELEASE_STATE_UNSUPPORTED",
        state: toStr(releaseOperation.state),
      });
    }
    ctx.managedEntitlementOperationId = toStr(releaseOperation.managedEntitlementOperationId);
    ctx.managedSubscriptionInstanceId = toStr(releaseOperation.managedSubscriptionInstanceId);
    if (ctx.managedEntitlementOperationId) {
      ctx.releaseOperation = releaseOperation;
      ctx.entitlementReleaseNext = "local_operation_release";
      return prepareManagedEntitlementRelease(ctx, "BOOKING_CANCELLED", ctx.releaseBookingId);
    }
    return prepareOperationRelease(ctx, releaseOperation);
  }
  const operation = isObj(rows[0]) ? rows[0] : null;
  const operationEnvironment = toStr(operation?.managedEnvironment);
  const expectedOperationEnvironment = ctx.managedEnforcement?.environment;
  const operationEnvironmentMatches = expectedOperationEnvironment === "DEV"
    ? operationEnvironment === "DEV"
    : [null, "PROD"].includes(operationEnvironment);
  if (operation && ctx.managedEnforcement?.enabled === true && !operationEnvironmentMatches) {
    return finishError(ctx, 409, "Окружение операции подписки не совпало", {
      code: "MANAGED_SUBSCRIPTION_OPERATION_ENVIRONMENT_MISMATCH",
    });
  }
  if (ctx.caller === "split_create_preflight" && operation
    && toStr(operation.operationId) === ctx.operationId
    && operation.state === "PRECREATE_RESERVED") {
    const exactReservation = normalizeId(operation.exerciseId) === normalizeId(ctx.exerciseId)
      && normalizeId(operation.clientSubscriptionId) === normalizeId(ctx.clientSubscriptionId)
      && operation.planKey === ctx.planKey
      && operation.managedDecision?.policyDigest === ctx.managedRuntime?.policyDigest
      && toStr(operation.managedEntitlementOperationId)
      && toStr(operation.managedSubscriptionInstanceId) === ctx.managedRuntime?.subscriptionInstanceId;
    if (!exactReservation) {
      return finishPending(ctx, "Предварительный резерв не совпал с текущим контекстом", {
        code: "MANAGED_SUBSCRIPTION_PREFLIGHT_RESERVATION_MISMATCH",
      });
    }
    ctx.managedDecision = operation.managedDecision;
    ctx.managedEntitlementOperationId = toStr(operation.managedEntitlementOperationId);
    ctx.managedSubscriptionInstanceId = toStr(operation.managedSubscriptionInstanceId);
    return preparePrecreatedAttempt(ctx);
  }
  if (ctx.caller === "split_create_preflight" && operation
    && toStr(operation.operationId) === ctx.operationId
    && operation.state === "PRECREATE_ATTEMPTING") {
    const expectedRecoveryTarget = precreateRecoveryTarget(ctx);
    const exactReservation = expectedRecoveryTarget
      && exactPrecreateRecoveryTarget(operation.precreateRecoveryTarget, expectedRecoveryTarget)
      && normalizeId(operation.actorClientId) === normalizeId(ctx.actorClientId)
      && normalizeId(operation.clientSubscriptionId) === normalizeId(ctx.clientSubscriptionId)
      && operation.planKey === ctx.planKey
      && operation.managedDecision?.policyDigest === ctx.managedRuntime?.policyDigest
      && toStr(operation.managedEntitlementOperationId)
      && toStr(operation.managedSubscriptionInstanceId) === ctx.managedRuntime?.subscriptionInstanceId;
    if (!exactReservation) {
      return finishPending(ctx, "Попытка создания игры не совпала с точной целью восстановления", {
        code: "MANAGED_SUBSCRIPTION_PREFLIGHT_RECOVERY_TARGET_MISMATCH",
      });
    }
    ctx.precreateRecoveryTarget = expectedRecoveryTarget;
    ctx.precreatedAttemptOperation = operation;
    ctx.managedDecision = operation.managedDecision;
    ctx.managedEntitlementOperationId = toStr(operation.managedEntitlementOperationId);
    ctx.managedSubscriptionInstanceId = toStr(operation.managedSubscriptionInstanceId);
    return prepareUserGet(
      ctx,
      "precreated_attempt_lookup",
      `/end-user/api/v1/${ctx.tenantKey}/exercises?date=${encodeURIComponent(expectedRecoveryTarget.serviceDate)}&includePast=true&past=true&size=1000`,
    );
  }
  if (ctx.sameExerciseBooking) {
    if (operation
      && ctx.managedActivationRequired
      && operation.state === "CONFIRMED"
      && operation.activationState === "PENDING") {
      const stableBookingId = bookingId(ctx.sameExerciseBooking)
        || toStr(operation.bookingId || operation.upstreamBookingId);
      if (!stableBookingId) {
        return finishPending(ctx, "Активная запись Viva найдена без устойчивого bookingId и требует сверки");
      }
      ctx.confirmedBookingId = stableBookingId;
      ctx.activationOperationId = toStr(operation.operationId);
      ctx.managedEntitlementOperationId = toStr(operation.managedEntitlementOperationId);
      ctx.managedSubscriptionInstanceId = toStr(operation.managedSubscriptionInstanceId);
      if (ctx.managedEntitlementOperationId
        && operation.managedEntitlementState !== "CONFIRMED") {
        return prepareManagedEntitlementConfirm(ctx);
      }
      return prepareManagedFirstUseActivation(ctx, stableBookingId);
    }
    if (operation && toStr(operation.operationId) === ctx.operationId) {
      const stableBookingId = bookingId(ctx.sameExerciseBooking)
        || toStr(operation.bookingId || operation.upstreamBookingId);
      if (!stableBookingId) {
        return finishPending(ctx, "Активная запись Viva найдена без устойчивого bookingId и требует сверки");
      }
      ctx.immediateBookingId = stableBookingId;
      ctx.managedEntitlementOperationId = toStr(operation.managedEntitlementOperationId);
      ctx.managedSubscriptionInstanceId = toStr(operation.managedSubscriptionInstanceId);
      return prepareConfirmedUpdate(ctx, ctx.sameExerciseBooking);
    }
    return finishError(ctx, 409, "По этому абонементу уже есть запись на выбранное событие", {
      code: DAILY_LIMIT_CODE,
      existingEvent: eventSummary(ctx.sameExerciseBooking),
    });
  }

  const now = new Date();
  const confirmedOperationWasCancelled = operationHasConfirmedCancellation(
    operation,
    ctx.cancelledSubscriptionBookings,
  );
  if (!operation) {
    ctx.step = "operation_insert";
    msg._subscriptionBooking = ctx;
    msg.payload = {
      _id: ctx.operationKey,
      tenantKey: ctx.tenantKey,
      clientSubscriptionId: ctx.clientSubscriptionId,
      serviceDate: ctx.serviceDate,
      operationId: ctx.operationId,
      actorClientId: ctx.actorClientId,
      exerciseId: ctx.exerciseId,
      category: ctx.category,
      planKey: ctx.planKey || null,
      limitMode: ctx.limitMode,
      managedEnvironment: ctx.managedEnforcement?.environment || null,
      managedDecision: ctx.managedDecision || null,
      activationState: ctx.managedActivationRequired ? "PENDING" : "NOT_REQUIRED",
      state: "PREPARED",
      attempts: 0,
      leaseUntil: new Date(now.getTime() + PREPARED_LEASE_MS).toISOString(),
      createdAt: now.toISOString(),
      updatedAt: now.toISOString(),
    };
    delete msg.error;
    return emit(OUTPUT_MONGO_INSERT);
  }

  if (operation.precreatedEntitlementReserved === true
    || operation.state === "PRECREATE_RECONCILIATION_REQUIRED"
    || toStr(operation.precreateReconciliationCode)
      === "MANAGED_SUBSCRIPTION_PREFLIGHT_CREATE_RECONCILIATION_REQUIRED") {
    return finishPending(ctx, "Созданная игра и резерв подписки требуют ручной сверки", {
      code: "MANAGED_SUBSCRIPTION_PREFLIGHT_CREATE_RECONCILIATION_REQUIRED",
    });
  }

  if (toStr(operation.operationId) === ctx.operationId) {
    if (operation.state === "CONFIRMED") {
      if (confirmedOperationWasCancelled) return prepareOperationReclaim(ctx, operation, now);
      return finishPending(
        ctx,
        "Подтверждённая ранее запись не найдена среди активных и требует сверки с Viva",
        { code: "SUBSCRIPTION_BOOKING_CONFIRMED_RECONCILIATION_REQUIRED" },
      );
    }
    if (operation.state === "FAILED") {
      return prepareOperationReclaim(ctx, operation, now);
    }
    if (operation.state === "PENDING_CONFIRMATION") {
      const pendingUntil = Date.parse(String(operation.pendingUntil || ""));
      if (!Number.isFinite(pendingUntil) || pendingUntil > now.getTime()) {
        return finishPending(ctx, "Предыдущая попытка ещё ожидает подтверждения Viva");
      }
      return prepareExpiredPendingReconciliation(ctx, operation);
    }
    if (operation.state === "PRECREATE_RESERVING") {
      const precreateLeaseUntil = Date.parse(String(operation.precreateLeaseUntil || ""));
      if (!Number.isFinite(precreateLeaseUntil) || precreateLeaseUntil > now.getTime()) {
        return finishPending(ctx, "Предварительный резерв подписки ещё выполняется");
      }
      return prepareManagedEntitlementReserve(ctx);
    }
    if (operation.state === "PREPARED") return preparePreaccept(ctx);
  }

  const leaseUntil = Date.parse(String(operation.leaseUntil || ""));
  const pendingUntil = Date.parse(String(operation.pendingUntil || ""));
  if (
    (operation.state === "PENDING_CONFIRMATION" && (!Number.isFinite(pendingUntil) || pendingUntil > now.getTime()))
    || ["PRECREATE_RESERVING", "PRECREATE_RESERVED", "PRECREATE_ATTEMPTING"].includes(operation.state)
    || (operation.state === "PREPARED" && Number.isFinite(leaseUntil) && leaseUntil > now.getTime())
  ) {
    return finishPending(ctx, "Другая операция уже резервирует дневное посещение");
  }

  if (operation.state === "PENDING_CONFIRMATION") {
    return prepareExpiredPendingReconciliation(ctx, operation);
  }

  const reclaimable = ["FAILED", "RELEASED"].includes(String(operation.state || ""))
    || (operation.state === "CONFIRMED" && confirmedOperationWasCancelled)
    || (operation.state === "PREPARED" && (!Number.isFinite(leaseUntil) || leaseUntil <= now.getTime()));
  if (!reclaimable) {
    const details = operation.state === "CONFIRMED"
      ? { code: "SUBSCRIPTION_BOOKING_CONFIRMED_RECONCILIATION_REQUIRED" }
      : null;
    return finishPending(ctx, "Дневное посещение уже обрабатывается или требует сверки с Viva", details);
  }
  return prepareOperationReclaim(ctx, operation, now);
}

if (ctx.step === "expired_pending_reconciliation") {
  const operation = ctx.expiredPendingOperation;
  if (!operation || !isHttpOk(msg.statusCode) || !hasCompleteBookingList(msg.payload)) {
    return finishPending(ctx, "Просроченная операция требует сверки с Viva");
  }
  const actorClientId = normalizeId(operation.actorClientId);
  const clientSubscriptionId = normalizeId(operation.clientSubscriptionId);
  if (!actorClientId || !clientSubscriptionId) {
    return finishPending(ctx, "Просроченная операция не содержит устойчивой идентичности для сверки");
  }
  const actorBookings = extractItems(msg.payload).filter((booking) => (
    isObj(booking) && normalizeId(bookingClientId(booking)) === actorClientId
  ));
  if (actorBookings.some((booking) => !bookingSubscriptionId(booking))) {
    return finishPending(ctx, "Viva вернула запись без связи с абонементом; требуется сверка");
  }
  const exactBookings = actorBookings.filter((booking) => (
    normalizeId(bookingSubscriptionId(booking)) === clientSubscriptionId
  ));
  if (exactBookings.some((booking) => !isInactiveBooking(booking))) {
    return finishPending(ctx, "Просроченная операция подтверждена активной записью Viva");
  }
  ctx.managedEntitlementOperationId = toStr(operation.managedEntitlementOperationId);
  ctx.managedSubscriptionInstanceId = toStr(operation.managedSubscriptionInstanceId);
  if (ctx.managedEntitlementOperationId) {
    ctx.managedEnvironment = toStr(operation.managedEnvironment) || "PROD";
    ctx.entitlementReleaseNext = "expired_pending_release";
    return prepareManagedEntitlementRelease(ctx, "PROVIDER_REJECTED");
  }
  return prepareExpiredPendingRelease(ctx, operation);
}

if (ctx.step === "operation_expired_pending_release") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Просроченная операция была изменена параллельно и требует повторной проверки");
  }
  return prepareOperationFind(ctx);
}

if (ctx.step === "operation_insert") {
  if (msg.error || !mongoInserted(msg.payload, ctx.operationKey)) {
    return finishPending(ctx, "Другая операция одновременно заняла дневное посещение");
  }
  return preparePreaccept(ctx);
}

if (ctx.step === "precreated_attempt_lookup") {
  const operation = ctx.precreatedAttemptOperation;
  const recoveryTarget = ctx.precreateRecoveryTarget;
  if (!operation || !recoveryTarget || !isHttpOk(msg.statusCode)
    || !hasBookingListShape(msg.payload) || !hasCompleteBookingList(msg.payload)) {
    return finishPending(ctx, "Список Viva для восстановления создания игры недоступен или неполон", {
      code: "MANAGED_SUBSCRIPTION_PREFLIGHT_CREATE_RECONCILIATION_REQUIRED",
    });
  }
  const matches = extractItems(msg.payload).filter((exercise) => (
    isObj(exercise) && exerciseMatchesPrecreateRecovery(exercise, recoveryTarget)
  ));
  if (matches.length !== 1) {
    return finishPending(ctx, "Созданную игру нельзя однозначно восстановить по точной цели", {
      code: "MANAGED_SUBSCRIPTION_PREFLIGHT_CREATE_RECONCILIATION_REQUIRED",
      recoveryMatchCount: matches.length,
    });
  }
  const recoveredExerciseId = toStr(matches[0].id || matches[0].exerciseId || matches[0].uuid);
  const storedExerciseId = normalizeId(operation.exerciseId);
  if (!recoveredExerciseId || (storedExerciseId !== normalizeId(recoveryTarget.placeholderExerciseId)
    && storedExerciseId !== normalizeId(recoveredExerciseId))) {
    return finishPending(ctx, "Сохранённая операция расходится с найденной игрой Viva", {
      code: "MANAGED_SUBSCRIPTION_PREFLIGHT_RECOVERY_TARGET_MISMATCH",
    });
  }
  delete ctx.precreatedAttemptOperation;
  return preparePrecreatedRecoveryBind(ctx, operation, recoveredExerciseId);
}

if (ctx.step === "operation_precreated_recover") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Найденная игра Viva ожидает атомарной локальной привязки", {
      code: "MANAGED_SUBSCRIPTION_PREFLIGHT_RECOVERY_BIND_PENDING",
    });
  }
  return finishManagedCreatePreflight(ctx, "PREFLIGHT_CREATE_RECOVERED");
}

if (ctx.step === "operation_reclaim") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Другая операция одновременно заняла дневное посещение");
  }
  return preparePreaccept(ctx);
}

if (ctx.step === "operation_preaccept") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Не удалось подтвердить владельца атомарной операции");
  }
  if (ctx.caller === "split_create_preflight") {
    return prepareManagedRuntimeContext(ctx, "managed_runtime_recheck");
  }
  return prepareUserGet(
    ctx,
    "exercise_recheck",
    `/end-user/api/v1/${ctx.tenantKey}/exercises/${encodeURIComponent(ctx.exerciseId)}`,
  );
}

if (ctx.step === "operation_precreated_promote") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Предварительный резерв изменился до записи Viva", {
      code: "MANAGED_SUBSCRIPTION_PREFLIGHT_PROMOTION_PENDING",
    });
  }
  return prepareBookingCreate(ctx);
}

if (ctx.step === "operation_precreated_reconciliation") {
  return finishPending(ctx, "Созданная игра требует сверки; резерв подписки сохранён", {
    code: "MANAGED_SUBSCRIPTION_PREFLIGHT_CREATE_RECONCILIATION_REQUIRED",
    localBindingConfirmed: !msg.error && mongoMatched(msg.payload) === 1,
  });
}

if (ctx.step === "operation_precreated_attempt") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Не удалось зафиксировать попытку создания игры до Viva", {
      code: "MANAGED_SUBSCRIPTION_PREFLIGHT_ATTEMPT_BIND_PENDING",
    });
  }
  return finishManagedCreatePreflight(ctx);
}

if (ctx.step === "operation_precreate_abort") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Льгота освобождена, но локальный резерв требует сверки", {
      code: "MANAGED_SUBSCRIPTION_PREFLIGHT_ABORT_BIND_PENDING",
    });
  }
  const failure = ctx.finalFailure || {};
  return finishError(
    ctx,
    Number(failure.statusCode) || 409,
    toStr(failure.message) || "Viva отклонила создание игры",
    { code: toStr(failure.rawCode) || "VIVA_EXERCISE_CREATE_REJECTED" },
  );
}

if (ctx.step === "booking_create") {
  const statusCode = Number(msg.statusCode) || null;
  if (!isHttpOk(statusCode)) {
    const rawMessage = toStr(msg.payload?.message || msg.payload?.error || msg.error?.message);
    if (statusCode && statusCode >= 400 && statusCode < 500 && statusCode !== 408) {
      if (ctx.managedEntitlementOperationId) {
        ctx.finalFailure = {
          statusCode,
          message: rawMessage || "Viva отклонила создание записи",
          rawCode: toStr(msg.payload?.code),
        };
        ctx.entitlementReleaseNext = "persist_failure";
        return prepareManagedEntitlementRelease(ctx, "PROVIDER_REJECTED");
      }
      return prepareFailedUpdate(
        ctx,
        statusCode,
        rawMessage || "Viva отклонила создание записи",
        toStr(msg.payload?.code),
      );
    }
    return finishPending(ctx, "Результат создания записи в Viva пока неизвестен");
  }
  ctx.correlationId = extractCorrelationId(msg.payload);
  ctx.immediateBookingId = bookingId(msg.payload) || null;
  const nowIso = new Date().toISOString();
  return prepareMongoUpdate(ctx, "operation_accept", {
    _id: ctx.operationKey,
    operationId: ctx.operationId,
    state: "PENDING_CONFIRMATION",
  }, {
    $set: {
      acceptedAt: nowIso,
      correlationId: ctx.correlationId || null,
      upstreamBookingId: ctx.immediateBookingId || null,
      updatedAt: nowIso,
    },
  });
}

if (ctx.step === "operation_accept") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Viva приняла запрос; локальное подтверждение ещё выполняется");
  }
  return prepareUserGet(ctx, "confirmation_bookings", `/end-user/api/v2/${ctx.tenantKey}/bookings?size=1000`);
}

if (ctx.step === "confirmation_bookings") {
  if (!isHttpOk(msg.statusCode)) {
    return finishPending(ctx, "Viva приняла запрос; список записей ещё недоступен");
  }
  if (!hasBookingListShape(msg.payload)) {
    return finishPending(ctx, "Viva приняла запрос; формат списка записей требует повторной проверки");
  }
  const confirmed = extractItems(msg.payload).find((booking) => (
    isObj(booking)
    && !isInactiveBooking(booking)
    && normalizeId(bookingExerciseId(booking)) === normalizeId(ctx.exerciseId)
    && normalizeId(bookingSubscriptionId(booking)) === normalizeId(ctx.clientSubscriptionId)
  ));
  if (!confirmed) {
    return finishPending(ctx, "Viva приняла запрос; запись ещё не появилась в активных");
  }
  if (!bookingId(confirmed) && !ctx.immediateBookingId) {
    return finishPending(ctx, "Viva показала запись без устойчивого bookingId; требуется повторная проверка");
  }
  return prepareConfirmedUpdate(ctx, confirmed);
}

if (ctx.step === "operation_confirm") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Запись появилась в Viva; локальное подтверждение ещё выполняется");
  }
  if (ctx.managedEntitlementOperationId && ctx.managedEntitlementConfirmed !== true) {
    return prepareManagedEntitlementConfirm(ctx);
  }
  if (ctx.managedActivationRequired) {
    return prepareManagedFirstUseActivation(ctx, ctx.confirmedBookingId);
  }
  return finishConfirmed(ctx, ctx.confirmedBookingId, 201);
}

if (ctx.step === "managed_entitlement_confirm") {
  const result = unwrapRecord(msg.payload);
  if (!isHttpOk(msg.statusCode) || !result || result.schemaVersion !== 1
    || result.outcome !== "CONFIRMED"
    || result.operationId !== ctx.managedEntitlementOperationId
    || result.subscriptionInstanceId !== (
      ctx.managedRuntime?.subscriptionInstanceId || ctx.managedSubscriptionInstanceId
    )
    || result.operationState !== "CONFIRMED"
    || !Number.isInteger(result.aggregateRevision) || result.aggregateRevision < 1) {
    return finishPending(ctx, "Запись подтверждена Viva; подтверждение льготы в ЦУП ожидает повтора", {
      code: "SUBSCRIPTION_ENTITLEMENT_CONFIRM_PENDING",
      upstreamStatus: Number(msg.statusCode) || null,
    });
  }
  ctx.managedEntitlementConfirmed = true;
  return prepareManagedEntitlementConfirmedUpdate(ctx);
}

if (ctx.step === "operation_entitlement_confirm") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Льгота подтверждена в ЦУП; локальная связь ожидает сверки", {
      code: "SUBSCRIPTION_ENTITLEMENT_CONFIRM_BIND_PENDING",
    });
  }
  if (ctx.managedActivationRequired) {
    return prepareManagedFirstUseActivation(ctx, ctx.confirmedBookingId);
  }
  return finishConfirmed(ctx, ctx.confirmedBookingId, 201);
}

if (ctx.step === "managed_first_use_activation") {
  const activation = unwrapRecord(msg.payload);
  if (!isHttpOk(msg.statusCode)
    || !activation
    || activation.schemaVersion !== 1
    || !["ACTIVATED", "ALREADY_ACTIVE"].includes(activation.outcome)
    || activation.state !== "ACTIVE"
    || activation.subscriptionInstanceId !== ctx.managedRuntime?.subscriptionInstanceId
    || !Number.isInteger(activation.revision)
    || !finiteDate(activation.activeFrom)
    || !finiteDate(activation.activeTo)) {
    return finishPending(ctx, "Запись подтверждена Viva; активация подписки в ЦУП ожидает повтора", {
      code: "SUBSCRIPTION_ACTIVATION_PENDING",
      upstreamStatus: Number(msg.statusCode) || null,
    });
  }
  return prepareActivationConfirmedUpdate(ctx, activation);
}

if (ctx.step === "operation_activation_confirm") {
  if (msg.error || Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Подписка активирована; локальная операция ожидает повторной сверки");
  }
  return finishConfirmed(ctx, ctx.confirmedBookingId, 201);
}

if (ctx.step === "operation_fail") {
  if (ctx.managedEntitlementOperationId
    && ctx.managedEntitlementReleased !== true
    && ctx.entitlementReleaseNext !== "finish_failure") {
    ctx.entitlementReleaseNext = "finish_failure";
    return prepareManagedEntitlementRelease(ctx, "PROVIDER_REJECTED");
  }
  const failure = ctx.finalFailure || {};
  return finishError(
    ctx,
    Number(failure.statusCode) || 409,
    toStr(failure.message) || "Viva отклонила создание записи",
    { code: toStr(failure.rawCode) || "VIVA_SUBSCRIPTION_BOOKING_REJECTED" },
  );
}

if (ctx.step === "managed_entitlement_release") {
  const result = unwrapRecord(msg.payload);
  if (!isHttpOk(msg.statusCode) || !result || result.schemaVersion !== 1
    || result.outcome !== "RELEASED"
    || result.operationId !== ctx.managedEntitlementOperationId
    || result.subscriptionInstanceId !== (
      ctx.managedRuntime?.subscriptionInstanceId || ctx.managedSubscriptionInstanceId
    )
    || !["FAILED", "COMPENSATED"].includes(result.operationState)
    || !Number.isInteger(result.aggregateRevision) || result.aggregateRevision < 1) {
    return finishPending(ctx, "Резерв льготы требует ручной сверки после неуспешного освобождения", {
      code: "SUBSCRIPTION_ENTITLEMENT_RELEASE_PENDING",
      upstreamStatus: Number(msg.statusCode) || null,
    });
  }
  ctx.managedEntitlementReleased = true;
  const next = ctx.entitlementReleaseNext;
  delete ctx.entitlementReleaseNext;
  if (next === "local_operation_release") {
    const operation = ctx.releaseOperation;
    delete ctx.releaseOperation;
    if (!isObj(operation)) {
      return finishPending(ctx, "Льгота освобождена; локальная операция требует сверки", {
        code: "SUBSCRIPTION_BOOKING_RELEASE_OPERATION_MISSING",
      });
    }
    return prepareOperationRelease(ctx, operation);
  }
  if (next === "expired_pending_release") {
    if (!isObj(ctx.expiredPendingOperation)) {
      return finishPending(ctx, "Льгота освобождена; просроченная операция требует сверки", {
        code: "SUBSCRIPTION_EXPIRED_OPERATION_MISSING",
      });
    }
    return prepareExpiredPendingRelease(ctx, ctx.expiredPendingOperation);
  }
  if (next === "persist_failure") {
    const failure = ctx.finalFailure || {};
    return prepareFailedUpdate(
      ctx,
      Number(failure.statusCode) || 409,
      toStr(failure.message) || "Viva отклонила создание записи",
      toStr(failure.rawCode) || "VIVA_SUBSCRIPTION_BOOKING_REJECTED",
    );
  }
  if (next === "precreate_abort") {
    return preparePrecreateAbortUpdate(ctx);
  }
  if (next === "pricing_not_configured") {
    return prepareFailedUpdate(
      ctx,
      409,
      "Доплата по льготе рассчитана, но её точная передача в Viva ещё не подключена",
      "MANAGED_SUBSCRIPTION_PROVIDER_PRICING_NOT_CONFIGURED",
    );
  }
  if (next === "finish_failure") {
    const failure = ctx.finalFailure || {};
    return finishError(
      ctx,
      Number(failure.statusCode) || 409,
      toStr(failure.message) || "Viva отклонила создание записи",
      { code: toStr(failure.rawCode) || "VIVA_SUBSCRIPTION_BOOKING_REJECTED" },
    );
  }
  return finishPending(ctx, "Льгота освобождена; продолжение операции требует сверки", {
    code: "SUBSCRIPTION_ENTITLEMENT_RELEASE_CONTINUATION_MISSING",
  });
}

if (ctx.step === "operation_release") {
  if (msg.error) {
    return finishError(ctx, 502, "Не удалось освободить дневное посещение", {
      code: "SUBSCRIPTION_BOOKING_RELEASE_PERSISTENCE_FAILED",
    });
  }
  if (Number(mongoMatched(msg.payload) || 0) < 1) {
    return finishPending(ctx, "Состояние дневного посещения изменилось; требуется повторная сверка", {
      code: "SUBSCRIPTION_BOOKING_RELEASE_RACE",
    });
  }
  return finishReleased(ctx, {
    operationFound: true,
    previousState: ctx.releasePreviousState || null,
  });
}

return finishError(ctx, 500, "Неизвестный этап серверной записи по абонементу", {
  code: "SUBSCRIPTION_BOOKING_STEP_UNSUPPORTED",
  step: ctx.step || null,
});

const isObj = (value) => Boolean(value) && typeof value === "object" && !Array.isArray(value);
const toStr = (value) => {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text || null;
};
const toNonNegativeInt = (value) => {
  if (value === null || value === undefined || value === "") return null;
  const number = Number(value);
  return Number.isInteger(number) && number >= 0 ? number : null;
};
const toFiniteDate = (value) => {
  const date = new Date(String(value || ""));
  return Number.isFinite(date.getTime()) ? date : null;
};
const floorRatio = (amount, numerator, denominator) => {
  const normalizedAmount = toNonNegativeInt(amount);
  const normalizedNumerator = toNonNegativeInt(numerator);
  const normalizedDenominator = toNonNegativeInt(denominator);
  if (normalizedAmount === null || normalizedNumerator === null
    || !normalizedDenominator) return null;
  const result = BigInt(normalizedAmount) * BigInt(normalizedNumerator)
    / BigInt(normalizedDenominator);
  return result <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(result) : null;
};

const input = isObj(msg._managedSubscriptionPolicyInput)
  ? msg._managedSubscriptionPolicyInput
  : null;
const policy = isObj(input?.policy) ? input.policy : null;
const instance = isObj(input?.instance) ? input.instance : null;
const target = isObj(input?.target) ? input.target : null;
const usage = isObj(input?.usage) ? input.usage : null;
const blockers = [];
const blockerCodes = new Set();

const block = (code, message, details = null) => {
  if (blockerCodes.has(code)) return;
  blockerCodes.add(code);
  blockers.push({ code, message, details: isObj(details) ? details : null });
};

const evaluatedAt = toFiniteDate(input?.evaluatedAt);
const decision = {
  eligible: false,
  policyVersion: toNonNegativeInt(policy?.policyVersion),
  blockers,
  usageUnits: null,
  activeServices: toNonNegativeInt(usage?.activeServices),
  maxActiveServices: policy?.activeServicesLimit?.enabled === true
    ? toNonNegativeInt(policy?.activeServicesLimit?.max)
    : null,
  dailyUsed: toNonNegativeInt(usage?.dailyUsed),
  dailyLimit: toNonNegativeInt(policy?.dailyUsageLimit),
  benefit: null,
  evaluatedAt: evaluatedAt?.toISOString() || new Date(0).toISOString(),
};

const finish = () => {
  decision.eligible = blockers.length === 0;
  msg._managedSubscriptionPolicyDecision = decision;
  return decision.eligible ? [msg, null] : [null, msg];
};

if (!input || !policy || !instance || !target || !usage || !evaluatedAt) {
  block(
    "MANAGED_SUBSCRIPTION_CONTEXT_INVALID",
    "Не удалось безопасно собрать контекст проверки подписки",
  );
  return finish();
}

if (policy.runtimeSchemaVersion !== 1) {
  block("POLICY_SCHEMA_UNSUPPORTED", "Версия runtime-схемы подписки не поддерживается");
}
if (policy.status !== "PUBLISHED") {
  block("POLICY_NOT_PUBLISHED", "Правила подписки ещё не опубликованы");
}
if (!Number.isInteger(policy.policyVersion) || policy.policyVersion < 1) {
  block("POLICY_VERSION_INVALID", "Версия правил подписки некорректна");
}
if (!toStr(policy.subscriptionTypeId) || !toStr(instance.subscriptionTypeId)
  || !toStr(instance.subscriptionInstanceId)) {
  block("SUBSCRIPTION_INSTANCE_INVALID", "Идентичность экземпляра подписки не подтверждена");
} else if (policy.subscriptionTypeId !== instance.subscriptionTypeId) {
  block("SUBSCRIPTION_TYPE_MISMATCH", "Экземпляр подписки связан с другим типом правил");
}
if (instance.policyVersion !== policy.policyVersion) {
  block("POLICY_VERSION_MISMATCH", "Экземпляр подписки связан с другой версией правил", {
    instancePolicyVersion: instance.policyVersion ?? null,
    evaluatedPolicyVersion: policy.policyVersion ?? null,
  });
}
if (target.resolutionSource !== "SERVER") {
  block("TARGET_NOT_SERVER_RESOLVED", "Параметры события должны быть подтверждены сервером");
}

const policyEffectiveAt = toFiniteDate(policy.effectiveAt);
if (!policyEffectiveAt) {
  block("POLICY_EFFECTIVE_AT_INVALID", "Дата вступления правил в силу некорректна");
} else if (policyEffectiveAt.getTime() > evaluatedAt.getTime()) {
  block("POLICY_NOT_EFFECTIVE", "Правила подписки ещё не вступили в силу", {
    effectiveAt: policyEffectiveAt.toISOString(),
  });
}

const activeFrom = toFiniteDate(instance.activeFrom);
const activeTo = toFiniteDate(instance.activeTo);
if (!activeFrom || !activeTo || activeFrom.getTime() > activeTo.getTime()) {
  block("SUBSCRIPTION_VALIDITY_INVALID", "Срок действия подписки не подтверждён");
}
const frozenUntilRaw = toStr(instance.frozenUntil);
const frozenUntil = toFiniteDate(instance.frozenUntil);
if (frozenUntilRaw && !frozenUntil) {
  block("SUBSCRIPTION_FREEZE_STATE_INVALID", "Срок заморозки подписки некорректен");
}
if (instance.state === "FROZEN") {
  block("SUBSCRIPTION_FROZEN", "Подписка заморожена", {
    frozenUntil: frozenUntil?.toISOString() || null,
  });
} else if (instance.state !== "ACTIVE") {
  const stateCode = instance.state === "EXPIRED"
    ? "SUBSCRIPTION_EXPIRED"
    : "SUBSCRIPTION_NOT_ACTIVE";
  block(stateCode, "Подписка сейчас недоступна для записи", {
    state: toStr(instance.state),
  });
}
if (activeFrom && evaluatedAt.getTime() < activeFrom.getTime()) {
  block("SUBSCRIPTION_NOT_ACTIVE", "Срок действия подписки ещё не начался", {
    activeFrom: activeFrom.toISOString(),
  });
}
if (activeTo && evaluatedAt.getTime() > activeTo.getTime()) {
  block("SUBSCRIPTION_EXPIRED", "Срок действия подписки закончился", {
    activeTo: activeTo.toISOString(),
  });
}
const noShowBlockedUntilRaw = toStr(instance.noShowBlockedUntil);
const noShowBlockedUntil = toFiniteDate(instance.noShowBlockedUntil);
if (noShowBlockedUntilRaw && !noShowBlockedUntil) {
  block("SUBSCRIPTION_NO_SHOW_STATE_INVALID", "Срок блокировки после неявки некорректен");
}
if (noShowBlockedUntil && noShowBlockedUntil.getTime() > evaluatedAt.getTime()) {
  block("SUBSCRIPTION_NO_SHOW_BLOCKED", "Запись по подписке временно заблокирована после неявки", {
    blockedUntil: noShowBlockedUntil.toISOString(),
  });
}

const startsAt = toFiniteDate(target.startsAt);
const durationMinutes = toNonNegativeInt(target.durationMinutes);
const stationId = toStr(target.stationId);
const category = toStr(target.category);
const action = toStr(input.action);
const actionCategory = {
  CREATE_GAME: "GAME",
  JOIN_GAME: "GAME",
  BOOK_GROUP_TRAINING: "GROUP_TRAINING",
  BOOK_TOURNAMENT: "TOURNAMENT",
  PURCHASE_ADD_ON_PRODUCT: "ADD_ON_PRODUCT",
}[action];

if (!startsAt || !durationMinutes || !stationId || !actionCategory) {
  block("TARGET_INVALID", "Параметры события неполны или некорректны");
} else {
  if (category !== actionCategory) {
    block("TARGET_CATEGORY_MISMATCH", "Категория события не совпадает с действием", {
      action,
      category,
    });
  }
  if (startsAt.getTime() <= evaluatedAt.getTime()) {
    block("TARGET_IN_PAST", "Нельзя использовать подписку для уже начавшегося события");
  }
  if (
    activeTo
    && startsAt.getTime() > activeTo.getTime()
    && policy.lifecycle?.allowBookingsAfterExpiry !== true
  ) {
    block("TARGET_AFTER_SUBSCRIPTION_EXPIRY", "Событие проходит после окончания подписки", {
      activeTo: activeTo.toISOString(),
    });
  }
}
if (target.currency !== "RUB") {
  block("CURRENCY_UNSUPPORTED", "Валюта события не поддерживается", {
    currency: toStr(target.currency),
  });
}

if (action === "CREATE_GAME") {
  if (policy.createGame?.enabled !== true) {
    block("SUBSCRIPTION_CREATE_DISABLED", "Создание игр по этой подписке отключено");
  } else if (!Array.isArray(policy.createGame.durationsMinutes)
    || !policy.createGame.durationsMinutes.includes(durationMinutes)) {
    block("DURATION_NOT_ALLOWED", "Такая длительность игры недоступна по подписке", {
      durationMinutes,
      allowedDurationsMinutes: Array.isArray(policy.createGame?.durationsMinutes)
        ? policy.createGame.durationsMinutes
        : [],
    });
  }
}
if (action === "JOIN_GAME") {
  if (policy.joinGame?.enabled !== true) {
    block("SUBSCRIPTION_JOIN_DISABLED", "Присоединение к играм по этой подписке отключено");
  } else {
    const minDuration = toNonNegativeInt(policy.joinGame.minDurationMinutes);
    const maxDuration = toNonNegativeInt(policy.joinGame.maxDurationMinutes);
    if (!minDuration || !maxDuration || !durationMinutes
      || durationMinutes < minDuration || durationMinutes > maxDuration) {
      block("DURATION_NOT_ALLOWED", "Длительность игры находится вне разрешённого диапазона", {
        durationMinutes,
        minDurationMinutes: minDuration,
        maxDurationMinutes: maxDuration,
      });
    }
  }
}

const timeZone = toStr(policy.timeZone);
const localDateParts = (date, zone) => {
  try {
    const parts = new Intl.DateTimeFormat("en-CA", {
      timeZone: zone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).formatToParts(date);
    const values = Object.fromEntries(parts.map((part) => [part.type, part.value]));
    if (!values.year || !values.month || !values.day) return null;
    return {
      key: `${values.year}-${values.month}-${values.day}`,
      dayNumber: Date.UTC(Number(values.year), Number(values.month) - 1, Number(values.day)) / 86400000,
    };
  } catch (_) {
    return null;
  }
};

const todayLocal = timeZone ? localDateParts(evaluatedAt, timeZone) : null;
const targetLocal = startsAt && timeZone ? localDateParts(startsAt, timeZone) : null;
if (!targetLocal) {
  block("TARGET_LOCAL_DATE_UNRESOLVED", "Не удалось определить локальную дату события");
}
const bookingWindowEnabled = policy.bookingWindow?.enabled === true;
const bookingWindowDays = bookingWindowEnabled
  ? toNonNegativeInt(policy.bookingWindow?.days)
  : null;
if (bookingWindowEnabled) {
  if (!todayLocal || !targetLocal || !bookingWindowDays) {
    block("BOOKING_WINDOW_UNRESOLVED", "Не удалось определить календарное окно записи");
  } else {
    const dayOffset = targetLocal.dayNumber - todayLocal.dayNumber;
    if (dayOffset < 0 || dayOffset >= bookingWindowDays) {
      block("BOOKING_WINDOW_EXCEEDED", "Событие находится за пределами окна записи по подписке", {
        bookingWindowDays,
        targetLocalDate: targetLocal.key,
        currentLocalDate: todayLocal.key,
      });
    }
  }
}
if (targetLocal) {
  if (Array.isArray(policy.usage?.blackoutDates)
    && policy.usage.blackoutDates.includes(targetLocal.key)) {
    block("SUBSCRIPTION_BLACKOUT_DATE", "На выбранную дату подписка не действует", {
      targetLocalDate: targetLocal.key,
    });
  }
}

if (targetLocal && toStr(usage.dailyBucketLocalDate) !== targetLocal.key) {
  block("USAGE_SNAPSHOT_BUCKET_MISMATCH", "Снимок использования рассчитан для другой даты", {
    expectedLocalDate: targetLocal.key,
    actualLocalDate: toStr(usage.dailyBucketLocalDate),
  });
}
if (policy.activeServicesLimit?.enabled === true
  && usage.activeServiceScope !== policy.activeServicesLimit?.scope) {
  block("ACTIVE_SERVICE_SCOPE_MISMATCH", "Снимок активных услуг рассчитан для другого состава записей", {
    expectedScope: toStr(policy.activeServicesLimit?.scope),
    actualScope: toStr(usage.activeServiceScope),
  });
}

const usageKeys = ["dailyUsed", "weeklyUsed", "monthlyUsed", "futureBookings"];
if (policy.activeServicesLimit?.enabled === true) usageKeys.push("activeServices");
if (usageKeys.some((key) => toNonNegativeInt(usage[key]) === null)) {
  block("USAGE_SNAPSHOT_INVALID", "Серверный снимок использования подписки некорректен");
}

const activeServices = toNonNegativeInt(usage.activeServices);
const activeServicesLimitEnabled = policy.activeServicesLimit?.enabled === true;
const maxActiveServices = activeServicesLimitEnabled
  ? toNonNegativeInt(policy.activeServicesLimit?.max)
  : null;
if (activeServicesLimitEnabled) {
  if (maxActiveServices === null || maxActiveServices < 1 || activeServices === null) {
    block("ACTIVE_SERVICES_LIMIT_INVALID", "Лимит активных услуг не настроен");
  } else if (activeServices >= maxActiveServices) {
    block("ACTIVE_SERVICES_LIMIT_REACHED", "Достигнут лимит активных услуг по подписке", {
      activeServices,
      maxActiveServices,
    });
  }
}

const usageUnits = durationMinutes
  ? toNonNegativeInt(policy.usageUnitsByDuration?.[String(durationMinutes)])
  : null;
decision.usageUnits = usageUnits;
if (usageUnits === null) {
  block("USAGE_UNITS_UNRESOLVED", "Не настроено списание для длительности события", {
    durationMinutes,
  });
}

const dailyUsed = toNonNegativeInt(usage.dailyUsed);
const dailyLimit = toNonNegativeInt(policy.dailyUsageLimit);
const hasDailyUsagePolicy = isObj(policy.dailyUsagePolicy);
const dailyUsageActions = hasDailyUsagePolicy
