  splitCtx.clientPhone = ctx.actorPhone || splitCtx.clientPhone || null;
  splitCtx.studioId = ctx.studioId || splitCtx.studioId || null;
  splitCtx.spot = ctx.confirmedSpot || splitCtx.spot || null;
