msg.url = TOKEN_URL_DEFAULT;
msg.headers = { "Content-Type": "application/x-www-form-urlencoded" };
msg.payload = tokenRequestBody;
msg.requestTimeout = TOKEN_REQUEST_TIMEOUT_MS;
msg.followRedirects = false;
msg.maxRedirects = 0;

